#import "SourceEditor.h"

#import <React/RCTConversions.h>

#import <react/renderer/components/RNSourceEditorSpec/ComponentDescriptors.h>
#import <react/renderer/components/RNSourceEditorSpec/EventEmitters.h>
#import <react/renderer/components/RNSourceEditorSpec/Props.h>
#import <react/renderer/components/RNSourceEditorSpec/RCTComponentViewHelpers.h>

#import "RCTFabricComponentsPlugins.h"

// Swift bridging header — auto-generated by the Swift compiler from the
// @objc surface in `SourceEditorImpl.swift`. Resolution differs by toolchain:
//   - iOS via Expo CNG (use_frameworks! → static_framework): the header
//     ends up at `<ReactNativeSourceEditor>/ReactNativeSourceEditor.framework/
//     Headers/ReactNativeSourceEditor-Swift.h`, so the angle form resolves.
//   - Bare RN macOS (no use_frameworks!, default library linkage): no
//     framework wrapper is built, so the angle form misses. The header
//     does land in the pod target's DerivedSources/, which is on the
//     compile-time header search path, so the quote form picks it up.
#if __has_include(<ReactNativeSourceEditor/ReactNativeSourceEditor-Swift.h>)
#import <ReactNativeSourceEditor/ReactNativeSourceEditor-Swift.h>
#else
#import "ReactNativeSourceEditor-Swift.h"
#endif

using namespace facebook::react;

@interface SourceEditor () <RCTSourceEditorViewProtocol>
@end

@implementation SourceEditor {
  RNSESourceEditorImpl *_impl;
  BOOL _hasMounted;
}

+ (ComponentDescriptorProvider)componentDescriptorProvider
{
  return concreteComponentDescriptorProvider<SourceEditorComponentDescriptor>();
}

- (instancetype)initWithFrame:(CGRect)frame
{
  if (self = [super initWithFrame:frame]) {
    static const auto defaultProps = std::make_shared<const SourceEditorProps>();
    _props = defaultProps;

    _impl = [[RNSESourceEditorImpl alloc] initWithFrame:frame];

    __weak SourceEditor *weakSelf = self;
    _impl.onChange = ^(NSString *text, NSInteger eventCount) {
      __strong SourceEditor *strongSelf = weakSelf;
      if (!strongSelf) return;
      auto eventEmitter = strongSelf->_eventEmitter;
      if (!eventEmitter) return;
      auto emitter = std::static_pointer_cast<const SourceEditorEventEmitter>(eventEmitter);
      emitter->onChangeText({
        .text = std::string([text UTF8String] ?: ""),
        .eventCount = static_cast<int>(eventCount)});
    };
    _impl.onFocus = ^(BOOL focused) {
      __strong SourceEditor *strongSelf = weakSelf;
      if (!strongSelf) return;
      auto eventEmitter = strongSelf->_eventEmitter;
      if (!eventEmitter) return;
      auto emitter = std::static_pointer_cast<const SourceEditorEventEmitter>(eventEmitter);
      emitter->onFocusChange({.focused = static_cast<bool>(focused)});
    };
    _impl.onSelection = ^(NSInteger start, NSInteger end) {
      __strong SourceEditor *strongSelf = weakSelf;
      if (!strongSelf) return;
      auto eventEmitter = strongSelf->_eventEmitter;
      if (!eventEmitter) return;
      auto emitter = std::static_pointer_cast<const SourceEditorEventEmitter>(eventEmitter);
      emitter->onSelectionChange(
        {.start = static_cast<double>(start), .end = static_cast<double>(end)});
    };

    self.contentView = _impl;
  }
  return self;
}

static NSString *_Nullable OptionalString(const std::string &value)
{
  return value.empty() ? nil : RCTNSStringFromString(value);
}

static bool HighlightsEqual(
    const std::vector<SourceEditorHighlightsStruct> &a,
    const std::vector<SourceEditorHighlightsStruct> &b)
{
  if (a.size() != b.size()) return false;
  for (size_t i = 0; i < a.size(); i++) {
    if (a[i].start != b[i].start || a[i].length != b[i].length ||
        a[i].color != b[i].color || a[i].fontStyle != b[i].fontStyle) {
      return false;
    }
  }
  return true;
}

- (void)updateProps:(Props::Shared const &)props oldProps:(Props::Shared const &)oldProps
{
  const auto &oldViewProps = *std::static_pointer_cast<const SourceEditorProps>(_props);
  const auto &newViewProps = *std::static_pointer_cast<const SourceEditorProps>(props);
  const bool firstMount = !_hasMounted;
  _hasMounted = YES;

  // Styling first, so text and highlights below are painted with it.
  if (firstMount || oldViewProps.theme != newViewProps.theme) {
    [_impl setTheme:RCTNSStringFromString(newViewProps.theme)];
  }
  // Codegen structs don't auto-generate operator==; compare fields directly.
  const auto &oldFont = oldViewProps.font;
  const auto &newFont = newViewProps.font;
  if (firstMount || oldFont.family != newFont.family || oldFont.boldFamily != newFont.boldFamily ||
      oldFont.italicFamily != newFont.italicFamily ||
      oldFont.boldItalicFamily != newFont.boldItalicFamily || oldFont.size != newFont.size ||
      oldFont.lineHeight != newFont.lineHeight) {
    [_impl setFontWithFamily:OptionalString(newFont.family)
                  boldFamily:OptionalString(newFont.boldFamily)
                italicFamily:OptionalString(newFont.italicFamily)
            boldItalicFamily:OptionalString(newFont.boldItalicFamily)
                        size:newFont.size
                  lineHeight:newFont.lineHeight];
  }
  const auto &oldColors = oldViewProps.colors;
  const auto &newColors = newViewProps.colors;
  if (firstMount || oldColors.background != newColors.background ||
      oldColors.foreground != newColors.foreground || oldColors.caret != newColors.caret ||
      oldColors.gutterBackground != newColors.gutterBackground ||
      oldColors.gutterText != newColors.gutterText ||
      oldColors.gutterCurrentLineText != newColors.gutterCurrentLineText ||
      oldColors.currentLine != newColors.currentLine) {
    [_impl setColorsWithBackground:RCTUIColorFromSharedColor(newColors.background)
                        foreground:RCTUIColorFromSharedColor(newColors.foreground)
                             caret:RCTUIColorFromSharedColor(newColors.caret)
                  gutterBackground:RCTUIColorFromSharedColor(newColors.gutterBackground)
                        gutterText:RCTUIColorFromSharedColor(newColors.gutterText)
             gutterCurrentLineText:RCTUIColorFromSharedColor(newColors.gutterCurrentLineText)
                       currentLine:RCTUIColorFromSharedColor(newColors.currentLine)];
  }
  if (firstMount || oldViewProps.lineNumbers != newViewProps.lineNumbers) {
    [_impl setLineNumbers:newViewProps.lineNumbers];
  }
  const auto &oldGutter = oldViewProps.gutter;
  const auto &newGutter = newViewProps.gutter;
  if (firstMount || oldGutter.fontFamily != newGutter.fontFamily ||
      oldGutter.fontSize != newGutter.fontSize || oldGutter.minimumWidth != newGutter.minimumWidth ||
      oldGutter.leadingInset != newGutter.leadingInset ||
      oldGutter.trailingInset != newGutter.trailingInset) {
    [_impl setGutterWithFontFamily:OptionalString(newGutter.fontFamily)
                          fontSize:newGutter.fontSize
                      minimumWidth:newGutter.minimumWidth
                      leadingInset:newGutter.leadingInset
                     trailingInset:newGutter.trailingInset];
  }
  if (firstMount || oldViewProps.wrapLines != newViewProps.wrapLines) {
    [_impl setWrapLines:newViewProps.wrapLines];
  }
  if (firstMount || oldViewProps.contentInsets.top != newViewProps.contentInsets.top ||
      oldViewProps.contentInsets.bottom != newViewProps.contentInsets.bottom ||
      oldViewProps.contentInsets.left != newViewProps.contentInsets.left ||
      oldViewProps.contentInsets.right != newViewProps.contentInsets.right) {
    [_impl setContentInsetsWithTop:newViewProps.contentInsets.top
                            bottom:newViewProps.contentInsets.bottom
                              left:newViewProps.contentInsets.left
                             right:newViewProps.contentInsets.right];
  }
  if (firstMount || oldViewProps.language != newViewProps.language) {
    [_impl setLanguage:RCTNSStringFromString(newViewProps.language)];
  }
  if (firstMount || oldViewProps.editable != newViewProps.editable) {
    [_impl setEditable:newViewProps.editable];
  }

  // Text, then the highlights computed for it. If the text is older than the
  // latest edit it is ignored, and so are its highlights.
  bool textCurrent = true;
  if (firstMount || oldViewProps.text != newViewProps.text ||
      oldViewProps.mostRecentEventCount != newViewProps.mostRecentEventCount) {
    textCurrent = [_impl setText:RCTNSStringFromString(newViewProps.text)
                      eventCount:newViewProps.mostRecentEventCount];
  }
  if (textCurrent &&
      (firstMount || oldViewProps.text != newViewProps.text ||
       !HighlightsEqual(oldViewProps.highlights, newViewProps.highlights))) {
    if (newViewProps.highlights.empty()) {
      [_impl setHighlights:nil];
    } else {
      NSMutableArray *spans = [NSMutableArray arrayWithCapacity:newViewProps.highlights.size()];
      for (const auto &span : newViewProps.highlights) {
        [spans addObject:@{
          @"start" : @(span.start),
          @"length" : @(span.length),
          @"color" : RCTNSStringFromString(span.color),
          @"fontStyle" : @(span.fontStyle),
        }];
      }
      [_impl setHighlights:spans];
    }
  }

  [super updateProps:props oldProps:oldProps];
}

- (void)prepareForRecycle
{
  [super prepareForRecycle];
  static const auto defaultProps = std::make_shared<const SourceEditorProps>();
  _props = defaultProps;
  _hasMounted = NO;
}

- (void)handleCommand:(const NSString *)commandName args:(const NSArray *)args
{
  RCTSourceEditorHandleCommand(self, commandName, args);
}

- (void)focus
{
  [_impl focusEditor];
}

- (void)blur
{
  [_impl blurEditor];
}

- (void)setSelection:(NSInteger)start end:(NSInteger)end
{
  [_impl setSelectionWithStart:start end:end];
}

@end

Class<RCTComponentViewProtocol> SourceEditorCls(void)
{
  return SourceEditor.class;
}
